test("member summary displays server totals, signed category bars, zero and unavailable amounts", async ({
  page,
  context,
}) => {
  await mockDetails(context);
  await page.goto("/members/1");
  await expect(page.locator(".member-total")).toHaveText([
    "18,014,398,509,481,986.246913578",
    "Amount unavailable",
    "0",
  ]);
  await expect(page.locator(".signed-bar .negative")).toHaveCount(1);
  await expect(
    page
      .locator(".category-label")
      .filter({ hasText: "Unrecognized source category" }),
  ).toContainText("−5 GBP");
  await expect(
    page.getByText("1 funding entry has an unknown currency", {
      exact: false,
    }),
  ).toBeVisible();
  await expect(page.locator(".declarations-list > li")).toHaveCount(2);
  await expect(
    page.getByRole("link", { name: "View all 2 declarations" }),
  ).toHaveAttribute("href", "/members/1/history");
});

.member-identity {
  margin: 0 0 28px;
  border-bottom: 1px solid var(--line);
}
.member-identity-title {
  display: flex;
  align-items: center;
  gap: 18px;
}
.member-identity h1 {
  margin: 0;
  font-size: clamp(1.8rem, 4vw, 2.8rem);
  line-height: 1.15;
  overflow-wrap: anywhere;
}
.member-identity > p {
  color: var(--muted);
  display: flex;
  flex-wrap: wrap;
  gap: 8px 24px;
  margin: 12px 0 16px;
}
.member-identity > p span {
  border-left: 1px solid var(--line);
  padding-left: 24px;
}
.member-tabs {
  display: flex;
  gap: 28px;
}
.member-tabs a {
  padding: 12px 0;
  color: var(--muted);
  text-decoration: none;
  border-bottom: 3px solid transparent;
}
.member-tabs a[aria-current="page"] {
  color: var(--text);
  border-color: var(--accent);
}
.member-overview,
.member-breakdown {
  min-width: 0;
}
.member-currency-totals {
  display: flex;
  flex-wrap: wrap;
  gap: 24px 48px;
  margin: 28px 0;
}
.member-currency-totals > div {
  min-width: 160px;
  max-width: 100%;
}
.member-currency-totals h3 {
  margin: 0 0 8px;
  color: var(--accent);
}
.member-page {
  margin-top: 24px;
}
.member-page .back-link {
  margin-bottom: 24px;
}
.member-identity .profile-type {
  margin-bottom: 0;
}
.member-summary-top {
  display: grid;
  grid-template-columns: minmax(0, 0.85fr) minmax(0, 1.15fr);
  gap: 48px;
  padding-bottom: 32px;
  margin-bottom: 32px;
  border-bottom: 1px solid var(--line);
}
.member-overview .summary-context {
  margin-bottom: 16px;
}
.member-total {
  font-size: clamp(1.8rem, 3.2vw, 2.7rem);
}
.member-breakdown {
  border-left: 1px solid var(--line);
  padding-left: 32px;
}
.member-breakdown .category-label {
  font-size: 13px;
  line-height: 1.65;
}
.member-breakdown .category-label .amount {
  flex-shrink: 0;
  max-width: 45%;
}
.member-page .declaration {
  padding: 18px 0;
}
.member-page .funding-list {
  margin-top: 12px;
}
@media (max-width: 800px) {
  .member-summary-top {
    grid-template-columns: minmax(0, 1fr);
    gap: 24px;
  }
  .member-breakdown {
    border-left: 0;
    padding-left: 0;
  }
}
